// Native googleSheets node outputs one item per data row (headers as keys).
// Try to use static data to track last processed row count; fall back to
// processing all rows if the task runner does not support static data.
let allRows;
try {
  allRows = $input.all().map(i => ({ ...i.json }));
  const sd  = $getWorkflowStaticData('global');
  const lastRow = typeof sd.lastRow === 'number' ? sd.lastRow : 0;
  sd.lastRow = allRows.length;
  const newRows = allRows.slice(lastRow, lastRow + 10);
  if (newRows.length === 0) return [];
  return newRows.map(row => ({ json: row }));
} catch(e) {
  // $getWorkflowStaticData unavailable (task runner) — emit all rows.
  allRows = allRows || $input.all().map(i => ({ ...i.json }));
  if (allRows.length === 0) return [];
  return allRows.slice(0, 10).map(row => ({ json: row }));
}

const row = $input.item.json;

const employerName = String(row['Employer Name'] || '').trim();
const employerBirthdayRaw = String(row['Employer Birthday'] || '').trim();
const maidName = String(row['Maid Name'] || '').trim();
const maidBirthdayRaw = String(row['Maid Birthday'] || '').trim();

const monthMap = {
  jan: 1, january: 1,
  feb: 2, february: 2,
  mar: 3, march: 3,
  apr: 4, april: 4,
  may: 5,
  jun: 6, june: 6,
  jul: 7, july: 7,
  aug: 8, august: 8,
  sep: 9, september: 9,
  oct: 10, october: 10,
  nov: 11, november: 11,
  dec: 12, december: 12,
};

function parseDate(str) {
  if (!str) return null;
  str = str.trim();
  const textMatch = str.match(/^(\d{1,2})\s+([a-zA-Z]+)\s+(\d{4})$/);
  if (textMatch) {
    const day   = parseInt(textMatch[1]);
    const month = monthMap[textMatch[2].toLowerCase()];
    const year  = parseInt(textMatch[3]);
    if (month) return year + '-' + String(month).padStart(2,'0') + '-' + String(day).padStart(2,'0');
  }
  const numMatch = str.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/);
  if (numMatch) {
    const day   = parseInt(numMatch[1]);
    const month = parseInt(numMatch[2]);
    const year  = parseInt(numMatch[3]);
    return year + '-' + String(month).padStart(2,'0') + '-' + String(day).padStart(2,'0');
  }
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return str;
  return null;
}

const pad = n => String(n).padStart(2, '0');

function nextBirthday(isoDate) {
  if (!isoDate) return { next: '', nextPlusOne: '' };
  const parts  = isoDate.split('-');
  const bMonth = parseInt(parts[1]) - 1;
  const bDay   = parseInt(parts[2]);
  const today  = new Date();
  let next     = new Date(today.getFullYear(), bMonth, bDay);
  if (next <= today) next = new Date(today.getFullYear() + 1, bMonth, bDay);
  const end = new Date(next);
  end.setDate(end.getDate() + 1);
  return {
    next:        next.getFullYear() + '-' + pad(next.getMonth() + 1) + '-' + pad(next.getDate()),
    nextPlusOne: end.getFullYear()  + '-' + pad(end.getMonth()  + 1) + '-' + pad(end.getDate()),
  };
}

const employerBD = nextBirthday(parseDate(employerBirthdayRaw));
const maidBD     = nextBirthday(parseDate(maidBirthdayRaw));

return {
  json: {
    EMPLOYER_NAME:                   employerName.toUpperCase(),
    EMPLOYER_NEXT_BIRTHDAY:          employerBD.next,
    EMPLOYER_NEXT_BIRTHDAY_PLUS_ONE: employerBD.nextPlusOne,
    MAID_NAME:                       maidName.toUpperCase(),
    MAID_NEXT_BIRTHDAY:              maidBD.next,
    MAID_NEXT_BIRTHDAY_PLUS_ONE:     maidBD.nextPlusOne,
  }
};
